# Salt Whisperer v2 content source. mg = USDA SR Legacy sodium (mg/100 g) x grams / 100, rounded.
# Run: python3 build_content.py  -> content.js + CONTENT_REVIEW.md
FOODS=[]; PARTS={}; PLATES=[]; COMPARES=[]
def F(id,name,emoji,cat,serving,fdc,grams,lvl,teach,swap,sn=False,**kw):
    FOODS.append(dict(id=id,name=name,emoji=emoji,cat=cat,serving=serving,fdc=fdc,grams=grams,lvl=lvl,teach=teach,swap=swap,sn=sn,**kw))
def E(id,name,emoji,cat,serving,mg,lvl,teach,swap,src,note,sn=False,**kw):
    FOODS.append(dict(id=id,name=name,emoji=emoji,cat=cat,serving=serving,fdc=None,mg=mg,lvl=lvl,teach=teach,swap=swap,sn=sn,src=src,note=note,**kw))
def X(id,name,emoji,serving,fdc,grams):
    PARTS[id]=dict(id=id,name=name,emoji=emoji,serving=serving,fdc=fdc,grams=grams)
def P(id,name,emoji,slot,parts,teach,swap,smart=False,**kw):
    PLATES.append(dict(id=id,name=name,emoji=emoji,slot=slot,parts=parts,teach=teach,swap=swap,smart=smart,**kw))
def C(id,a,b,teach,swap,lvl=4,**kw):
    COMPARES.append(dict(id=id,a=a,b=b,teach=teach,swap=swap,lvl=lvl,**kw))

